svg.script:
// Adapted from https://posetek-loader-v2--posetek-mobile-mockup-v2.netlify.app/v2/runner.mjs
// Same 33-point geometry, depth ordering and 900 ms stride; mounts the supplied SVG.
(() => {
/** Original anatomical rig and motion; MediaPipe names/indexing are the interface. */
const STRIDE_MS = 900;
const LANDMARK_NAMES = Object.freeze([
  'nose', 'left_eye_inner', 'left_eye', 'left_eye_outer',
  'right_eye_inner', 'right_eye', 'right_eye_outer', 'left_ear', 'right_ear',
  'mouth_left', 'mouth_right', 'left_shoulder', 'right_shoulder',
  'left_elbow', 'right_elbow', 'left_wrist', 'right_wrist',
  'left_pinky', 'right_pinky', 'left_index', 'right_index', 'left_thumb', 'right_thumb',
  'left_hip', 'right_hip', 'left_knee', 'right_knee', 'left_ankle', 'right_ankle',
  'left_heel', 'right_heel', 'left_foot_index', 'right_foot_index',
]);
// The connections match the pose overlay used by the website, including its
// nose-to-ear and ear-to-shoulder face/neck connections.
const SEGMENTS = Object.freeze([
  [11, 12], [11, 13], [13, 15], [15, 17], [15, 19], [15, 21], [17, 19],
  [12, 14], [14, 16], [16, 18], [16, 20], [16, 22], [18, 20],
  [11, 23], [12, 24], [23, 24],
  [23, 25], [25, 27], [27, 29], [29, 31], [27, 31],
  [24, 26], [26, 28], [28, 30], [30, 32], [28, 32],
  [0, 7], [0, 8], [7, 11], [8, 12],
].map(Object.freeze));
const TAU = Math.PI * 2;
const CAMERA = Object.freeze({ yaw: 25 * Math.PI / 180, scale: 43, centerX: 48, groundY: 90 });
const LENGTHS = Object.freeze({ thigh: 0.43, shin: 0.44, upperArm: 0.30, forearm: 0.27 });
const normalize = value => Number.isFinite(value) ? ((value % 1) + 1) % 1 : 0;
const precise = value => Number(value.toFixed(5));
// Cubic Hermite knots carry explicit velocities. Matching first/last values and
// velocities makes the periodic path C1, including its contact/flight joins.
function curve(phase, knots) {
  for (let i = 0; i < knots.length - 1; i++) {
    const [start, a, da] = knots[i];
    const [end, b, db] = knots[i + 1];
    if (phase <= end) {
      const span = end - start;
      const t = (phase - start) / span;
      const t2 = t * t, t3 = t2 * t;
      return (2 * t3 - 3 * t2 + 1) * a + (t3 - 2 * t2 + t) * span * da
        + (-2 * t3 + 3 * t2) * b + (t3 - t2) * span * db;
    }
  }
  return knots.at(-1)[1];
}

const FOOT_X = [
  [0, 0.30, -1.65], [0.32, -0.30, -1.85], [0.46, -0.48, 0],
  [0.62, -0.26, 2.0], [0.78, 0.22, 2.1], [0.90, 0.37, 0], [1, 0.30, -1.65],
];
const FOOT_CLEARANCE = [
  [0, 0, 0], [0.32, 0, 0], [0.48, 0.38, 2.25], [0.60, 0.51, 0],
  [0.75, 0.31, -1.65], [0.90, 0.08, -1.15], [1, 0, 0],
];
const FOOT_PITCH = [
  [0, 0.16, -2.5], [0.08, 0, 0], [0.18, 0, 0], [0.32, -0.80, -3.0],
  [0.46, -0.72, 2.0], [0.65, -0.10, 1.2], [0.82, 0.10, 0.6],
  [0.92, 0.23, 0], [1, 0.16, -2.5],
];

function rotateFoot(x, y, pitch) {
  return { x: x * Math.cos(pitch) - y * Math.sin(pitch), y: x * Math.sin(pitch) + y * Math.cos(pitch) };
}

function kneeFor(hip, ankle) {
  const dx = ankle.x - hip.x, dy = ankle.y - hip.y;
  const distance = Math.hypot(dx, dy);
  const along = (LENGTHS.thigh ** 2 - LENGTHS.shin ** 2 + distance ** 2) / (2 * distance);
  const height = Math.sqrt(Math.max(0, LENGTHS.thigh ** 2 - along ** 2));
  // The positive perpendicular places the knee forward, so it bends naturally.
  return { x: hip.x + dx / distance * along - dy / distance * height,
    y: hip.y + dy / distance * along + dx / distance * height, z: hip.z };
}

function armPoint(start, length, angle) {
  return { x: start.x + length * Math.sin(angle), y: start.y - length * Math.cos(angle), z: start.z };
}

function phaseName(phase) {
  return phase < 0.08 ? 'contact' : phase < 0.20 ? 'stance' : phase < 0.32 ? 'push-off' : phase < 0.48 ? 'flight' : 'recovery';
}

function poseAt(phase = 0) {
  const normalized = normalize(phase);
  const root = { x: 0, y: 0.845 + 0.025 * Math.cos(2 * TAU * (normalized - 0.38)), z: 0 };
  const bodyYaw = 0.065 * Math.sin(TAU * (normalized - 0.08));
  const landmarks = new Array(33);
  const put = (index, point) => { landmarks[index] = { index, name: LANDMARK_NAMES[index], ...point }; };
  // A restrained rigid trunk rotation adds depth without stretching the torso,
  // arms or face. Leg IK follows each hip while the central root stays fixed.
  const local = (x, y, z) => ({ x: root.x + x * Math.cos(bodyYaw) + z * Math.sin(bodyYaw),
    y: root.y + y, z: -x * Math.sin(bodyYaw) + z * Math.cos(bodyYaw) });

  // Rigid facial geometry retains all eleven canonical landmarks. There is no
  // enclosing circle or invented head outline in the overlay.
  const face = [
    [0.350, 0.690, 0],
    [0.315, 0.750, 0.022], [0.294, 0.755, 0.043], [0.271, 0.748, 0.062],
    [0.315, 0.750, -0.022], [0.294, 0.755, -0.043], [0.271, 0.748, -0.062],
    [0.205, 0.685, 0.081], [0.205, 0.685, -0.081],
    [0.325, 0.600, 0.027], [0.325, 0.600, -0.027],
  ];
  face.forEach(([x, y, z], index) => put(index, local(x, y, z)));

  const feet = {};
  for (const [side, offset, zSign] of [['left', 0, 1], ['right', 1, -1]]) {
    const legPhase = normalize(normalized + offset * 0.5);
    const hip = local(0, 0, zSign * 0.105);
    const shoulderLocal = { x: 0.13, y: 0.49, z: zSign * 0.19 };
    const shoulder = local(shoulderLocal.x, shoulderLocal.y, shoulderLocal.z);
    put(23 + offset, hip);
    put(11 + offset, shoulder);

    const pitch = curve(legPhase, FOOT_PITCH);
    const clearance = curve(legPhase, FOOT_CLEARANCE);
    const heelOffset = rotateFoot(-0.075, -0.06, pitch);
    const toeOffset = rotateFoot(0.16, -0.06, pitch);
    // A tiny smooth-max blends heel contact into toe contact without a velocity
    // discontinuity. The contact sole remains within 0.2mm of the virtual floor.
    const a = -heelOffset.y, b = -toeOffset.y;
    const contactHeight = (a + b + Math.sqrt((a - b) ** 2 + 0.0004 ** 2)) / 2;
    const ankle = { x: hip.x + curve(legPhase, FOOT_X), y: clearance + contactHeight, z: hip.z };
    const heel = { x: ankle.x + heelOffset.x, y: ankle.y + heelOffset.y, z: hip.z };
    const toe = { x: ankle.x + toeOffset.x, y: ankle.y + toeOffset.y, z: hip.z + zSign * 0.018 };
    put(25 + offset, kneeFor(hip, ankle));
    put(27 + offset, ankle);
    put(29 + offset, heel);
    put(31 + offset, toe);
    feet[side] = { phase: legPhase, stage: phaseName(legPhase), pitch, clearance,
      contact: legPhase <= 0.32, soleHeight: Math.min(heel.y, toe.y) };

    // Arms counter-swing the legs. Wrist, finger and thumb landmarks form a
    // compact relaxed hand that rotates rigidly with the forearm.
    const angle = TAU * legPhase;
    const upperAngle = -0.15 - 0.85 * Math.cos(angle - 0.10);
    const lowerAngle = upperAngle + 1.65 + 0.13 * Math.sin(angle);
    const elbow = armPoint(shoulderLocal, LENGTHS.upperArm, upperAngle);
    const wrist = armPoint(elbow, LENGTHS.forearm, lowerAngle);
    put(13 + offset, local(elbow.x, elbow.y, elbow.z));
    put(15 + offset, local(wrist.x, wrist.y, wrist.z));
    const finger = (along, across, depth) => ({
      x: wrist.x + along * Math.sin(lowerAngle) + across * Math.cos(lowerAngle),
      y: wrist.y - along * Math.cos(lowerAngle) + across * Math.sin(lowerAngle),
      z: wrist.z + zSign * depth,
    });
    for (const [index, along, across, depth] of [[17, 0.072, 0.012, 0.025], [19, 0.080, -0.008, -0.015], [21, 0.040, -0.030, 0.015]]) {
      const point = finger(along, across, depth);
      put(index + offset, local(point.x, point.y, point.z));
    }
  }

  const project = point => ({
    x: CAMERA.centerX + CAMERA.scale * (point.x * Math.cos(CAMERA.yaw) + point.z * Math.sin(CAMERA.yaw)),
    y: CAMERA.groundY - CAMERA.scale * point.y,
    depth: -point.x * Math.sin(CAMERA.yaw) + point.z * Math.cos(CAMERA.yaw),
  });
  const projected = landmarks.map(point => ({ index: point.index, name: point.name, ...project(point) }));
  return { phase: normalized, landmarks, projected, segments: SEGMENTS, root,
    rootProjected: project(root), anchor: { x: CAMERA.centerX, groundY: CAMERA.groundY },
    phaseInfo: feet, limbLengths: { ...LENGTHS }, bodyYawRadians: bodyYaw, camera: { yawDegrees: 25, scale: CAMERA.scale } };
}

const segmentDepth = (pair, pose) => (pose.projected[pair[0]].depth + pose.projected[pair[1]].depth) / 2;
/** Mount once, update existing nodes; the preview controller owns all timing. */
function createRunner(svg) {
  const bones = [...svg.querySelectorAll('[data-segment]')].map(node => ({ node, pair: node.getAttribute('data-segment').split(':').map(Number) }));
  const joints = [...svg.querySelectorAll('[data-landmark]')].map(node => ({ node, index: Number(node.getAttribute('data-landmark')) }));
  const boneLayer = svg.querySelector('[data-layer="bones"]');
  const jointLayer = svg.querySelector('[data-layer="landmarks"]');
  let boneOrder = bones.map(item => item.pair.join(':')).join('|');
  let jointOrder = joints.map(item => item.index).join(':');
  return {
    render(phase) {
      const pose = poseAt(phase);
      for (const { node, pair: [a, b] } of bones) {
        node.setAttribute('x1', precise(pose.projected[a].x)); node.setAttribute('y1', precise(pose.projected[a].y));
        node.setAttribute('x2', precise(pose.projected[b].x)); node.setAttribute('y2', precise(pose.projected[b].y));
      }
      for (const { node, index } of joints) {
        node.setAttribute('cx', precise(pose.projected[index].x)); node.setAttribute('cy', precise(pose.projected[index].y));
      }
      // Existing elements are re-ordered only when camera depth ordering changes.
      // Side colors remain tied to canonical indices, never the visible side.
      const sortedBones = [...bones].sort((a, b) => segmentDepth(a.pair, pose) - segmentDepth(b.pair, pose));
      const nextBoneOrder = sortedBones.map(item => item.pair.join(':')).join('|');
      if (nextBoneOrder !== boneOrder) { boneLayer.append(...sortedBones.map(item => item.node)); boneOrder = nextBoneOrder; }
      const sortedJoints = [...joints].sort((a, b) => pose.projected[a.index].depth - pose.projected[b.index].depth);
      const nextJointOrder = sortedJoints.map(item => item.index).join(':');
      if (nextJointOrder !== jointOrder) { jointLayer.append(...sortedJoints.map(item => item.node)); jointOrder = nextJointOrder; }
    },
  };
}

const runner = createRunner(document.querySelector('.pose-runner-v2'));
const systemMotion = matchMedia('(prefers-reduced-motion: reduce)');
let frame = null;
let previousTime = null;
let phase = 0;
const reduced = () => window.runnerReducedMotion || systemMotion.matches;
const canAnimate = () => !reduced() && document.visibilityState === 'visible';

function stop() {
  if (frame !== null) cancelAnimationFrame(frame);
  frame = null;
  previousTime = null;
}
function tick(time) {
  frame = null;
  if (!canAnimate()) return;
  if (previousTime !== null) phase = (phase + (time - previousTime) / STRIDE_MS) % 1;
  previousTime = time;
  runner.render(phase);
  frame = requestAnimationFrame(tick);
}
function syncAnimation() {
  stop();
  if (reduced()) runner.render(0);
  if (canAnimate()) frame = requestAnimationFrame(tick);
}
systemMotion.addEventListener('change', syncAnimation);
document.addEventListener('visibilitychange', syncAnimation);
window.addEventListener('pagehide', stop);
window.addEventListener('pageshow', syncAnimation);
syncAnimation();

})();
